def hes_existentes(apps, schema_editor):
    """Las conformidades registradas antes de la liberación por niveles ya valían como conformidad: quedan liberadas
    (con su línea si la orden tiene una sola). Los perfiles que crean órdenes también registran HES."""
    alias = schema_editor.connection.alias
    for hes in apps.get_model('compras', 'ConformidadServicio').objects.using(alias).all():
        items = list(apps.get_model('compras', 'OrdenCompraItem').objects.using(alias).filter(
            documento_id=hes.orden_compra_id))
        if len(items) == 1:
            hes.oc_item_id = items[0].pk
            hes.cantidad = (items[0].cantidad * hes.porcentaje / 100).quantize(Decimal('0.01'))
        hes.estado, hes.liberado_por_id, hes.liberado_en = 'LIBERADA', hes.conforme_por_id, hes.creado
        hes.save()
    for nombre in ('PerfilUsuario', 'PerfilAcceso'):
        for perfil in apps.get_model('core', nombre).objects.using(alias).all():
            if 'compras.oc' in perfil.acciones and 'compras.hes' not in perfil.acciones:
                perfil.acciones = list(perfil.acciones) + ['compras.hes']
                perfil.save(update_fields=['acciones'])


